    { source = "drop", pets = {
        { speciesID = 380, npcID = 62992, name = "Bucktooth Flapper", petType = 8, source = "drop", sourceInfo = "Bucktooth Flapper \"It's hard to know what's more dangerous: the teeth or the tail.\" Pet Battle The Jade Forest --" },
        { speciesID = 383, npcID = 61088, name = "Eternal Strider", petType = 9, source = "drop", sourceInfo = "Eternal Strider \"It seems like a trick to the eyes, but the eternal strider can walk across water, its small feet never breaking the surface.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 560, npcID = 62953, name = "Sea Gull", petType = 3, source = "drop", sourceInfo = "Sea Gull \"The seagull is a coastal scavenger often found near the docks.\" Pet Battle Frostwall, Krasarang Wilds, Talador, Tanaris --" },
        { speciesID = 562, npcID = 62991, name = "Coral Adder", petType = 8, source = "drop", sourceInfo = "Coral Adder \"The coral adder's venom is so deadly that one bite has been known to kill a full grown kodo beast.\" Pet Battle The Jade Forest --" },
        { speciesID = 564, npcID = 62994, name = "Emerald Turtle", petType = 9, source = "drop", sourceInfo = "Emerald Turtle \"It is difficult to believe that Shen-zin Su, on whose shell rests all of the Wandering Isle, began life as a tiny emerald turtle.\" Pet Battle Jade Forest --" },
        { speciesID = 565, npcID = 62997, name = "Jungle Darter", petType = 9, source = "drop", sourceInfo = "Jungle Darter \"In the jungle, every leaf could conceal a frog. Stop to check and it could be long gone.\" Pet Battle Jade Forest --" },
        { speciesID = 566, npcID = 62998, name = "Mirror Strider", petType = 9, source = "drop", sourceInfo = "Mirror Strider \"When preparing to travel to distant locations, Pandaren will traditionally capture a mirror strider and safely relocate it to another body of water.\" Pet Battle The Jade Forest --" },
        { speciesID = 567, npcID = 62999, name = "Temple Snake", petType = 8, source = "drop", sourceInfo = "Temple Snake \"The Jade Forest's pandaren consider these reptiles distant relatives of the revered Jade Serpent, Yu'lon.\" Pet Battle The Jade Forest --" },
        { speciesID = 568, npcID = 63001, name = "Silkbead Snail", petType = 5, source = "drop", sourceInfo = "Silkbead Snail \"Hides in shell to escape claws of nearby crabs.\" Pet Battle Gorgrond, Spires of Arak, Talador, The Jade Forest --" },
        { speciesID = 569, npcID = 63002, name = "Garden Frog", petType = 9, source = "drop", sourceInfo = "Garden Frog \"One of the stranger nuisances to horticulturalists, garden frogs can cause untold damage to gardens.\" Pet Battle Azsuna, Highmountain, The Jade Forest --" },
        { speciesID = 570, npcID = 63003, name = "Masked Tanuki", petType = 5, source = "drop", sourceInfo = "Masked Tanuki \"There's a raging debate over whether tanukis are raccoons or dogs, but the distinction seems trivial when they're gnawing on your femur.\" Pet Battle The Jade Forest --" },
        { speciesID = 571, npcID = 63004, name = "Grove Viper", petType = 8, source = "drop", sourceInfo = "Grove Viper \"The Jade Forest's mountain hozen fear these venomous reptiles and often hunt them out of pure spite.\" Pet Battle The Jade Forest --" },
        { speciesID = 572, npcID = 63005, name = "Spirebound Crab", petType = 9, source = "drop", sourceInfo = "Spirebound Crab \"These tiny arthropods are Pandaria natives that call the area of the Windless Isle their home.\" Pet Battle The Jade Forest --" },
        { speciesID = 573, npcID = 63006, name = "Sandy Petrel", petType = 3, source = "drop", sourceInfo = "Sandy Petrel \"The sandy petrel flies high above the Windless Isle, safe from landbound predators.\" Pet Battle Jade Forest --" },
        { speciesID = 650, npcID = 63365, name = "Terrible Turnip", petType = 7, source = "drop", sourceInfo = "Terrible Turnip \"And you thought turnips at the dinner table were bad.\" Drop: World Drop Valley of the Four Winds --" },
        { speciesID = 677, npcID = 64246, name = "Shy Bandicoon", petType = 5, source = "drop", sourceInfo = "Shy Bandicoon \"A goblin alchemist once claimed that the bite of this raccoon gave him the gift of prophecy. Turns out, it was just rabies.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 678, npcID = 63304, name = "Jungle Grub", petType = 8, source = "drop", sourceInfo = "Jungle Grub \"These little green grubs are native to wilds of Pandaria. Its verdant coloration camouflages it from would-be predators.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 679, npcID = 64248, name = "Summit Kid", petType = 8, source = "drop", sourceInfo = "Summit Kid \"You'll often find them perched high atop impossibly high and remote stone outcroppings. There are few creatures as sure of foot.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 680, npcID = 63953, name = "Kuitan Mongoose", petType = 9, source = "drop", sourceInfo = "Kuitan Mongoose \"The mongoose is prized for its ability to drive off poisonous snakes. Rikk-tikk-tikki-tikki-tchk!\" Pet Battle Townlong Steppes --" },
        { speciesID = 699, npcID = 63715, name = "Jumping Spider", petType = 8, source = "drop", sourceInfo = "Jumping Spider \"This terrifying and highly venomous species leaps onto its prey from the Jade Forest's dense canopy.\" Pet Battle The Jade Forest --" },
        { speciesID = 702, npcID = 63919, name = "Leopard Tree Frog", petType = 9, source = "drop", sourceInfo = "Leopard Tree Frog \"The leopard tree frog was named for the way it pounces from branch to branch.\" Pet Battle Gorgrond, The Jade Forest --" },
        { speciesID = 703, npcID = 63716, name = "Masked Tanuki Pup", petType = 5, source = "drop", sourceInfo = "Masked Tanuki Pup \"Many young raccoons rail against their strict curfews, complaining that dawn is way too early to go to bed.\" Pet Battle The Jade Forest --" },
        { speciesID = 706, npcID = 63062, name = "Bandicoon", petType = 5, source = "drop", sourceInfo = "Bandicoon \"The taciturn bandicoon's diet consists mostly of apples.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 707, npcID = 63064, name = "Bandicoon Kit", petType = 5, source = "drop", sourceInfo = "Bandicoon Kit \"Some druids say pandaren and raccoons are distant cousins, but never when a pandaren can hear them.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 708, npcID = 63094, name = "Malayan Quillrat", petType = 5, source = "drop", sourceInfo = "Malayan Quillrat \"Many believe that the quillrat is able to shoot its spines at aggressors.\" Pet Battle Valley of the Four Winds, Krasarang Wilds --" },
        { speciesID = 709, npcID = 63095, name = "Malayan Quillrat Pup", petType = 5, source = "drop", sourceInfo = "Malayan Quillrat Pup \"Although the wounds caused by the young quillrat are seldom fatal, most predators seek easier prey.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 710, npcID = 63096, name = "Marsh Fiddler", petType = 5, source = "drop", sourceInfo = "Marsh Fiddler \"Known to feast on the tasty plants in valley of the Four Winds.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 711, npcID = 63057, name = "Sifang Otter", petType = 9, source = "drop", sourceInfo = "Sifang Otter \"The sifang otter lives near rivers and is normally friendly and playful.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 712, npcID = 63358, name = "Sifang Otter Pup", petType = 9, source = "drop", sourceInfo = "Sifang Otter Pup \"Otters swim by propelling themselves with their powerful tails and flexing their long bodies. Very fast in the water.\" Pet Battle Valley of the Four Winds --" },
        { speciesID = 714, npcID = 65054, name = "Feverbite Hatchling", petType = 8, source = "drop", sourceInfo = "Feverbite Hatchling \"The common folk remedy to a feverbite hatchling's bite is to dance wildly and try to sweat out the toxins before they can take hold.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 716, npcID = 63288, name = "Amethyst Spiderling", petType = 8, source = "drop", sourceInfo = "Amethyst Spiderling \"A rarity among arachnids, these non-venomous critters feed solely on plants and fruit.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 717, npcID = 63291, name = "Savory Beetle", petType = 5, source = "drop", sourceInfo = "Savory Beetle \"The most delicious of the beetle family.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 718, npcID = 65124, name = "Luyu Moth", petType = 3, source = "drop", sourceInfo = "Luyu Moth \"A daring, narcissist insect willing to brave any threat in its pursuit of the spotlight.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 722, npcID = 65185, name = "Mei Li Sparkler", petType = 3, source = "drop", sourceInfo = "Mei Li Sparkler \"Feeds on small leaves and grass when full grown.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 723, npcID = 63293, name = "Spiny Terrapin", petType = 9, source = "drop", sourceInfo = "Spiny Terrapin \"Angering a spiny terrapin will cause it to withdraw into its shell and begin to spin wildly towards an attacker.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 724, npcID = 63550, name = "Alpine Foxling", petType = 8, source = "drop", sourceInfo = "Alpine Foxling \"Burrows deep into snowbanks to hide from predators.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 725, npcID = 63551, name = "Alpine Foxling Kit", petType = 8, source = "drop", sourceInfo = "Alpine Foxling Kit \"Occasionally sneaks bites of food from kills made by much larger animals.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 726, npcID = 63547, name = "Plains Monitor", petType = 8, source = "drop", sourceInfo = "Plains Monitor \"While stationary, the plains monitor will continuously flick its tail back and forth. From a distance this mimics the appearance of swaying tailgrass, camouflaging the lizard from aerial predators. Pet Battle Kun-Lau Summit --" },
        { speciesID = 727, npcID = 59702, name = "Prairie Mouse", petType = 5, source = "drop", sourceInfo = "Prairie Mouse \"On the prairie there are numerous rodents and other small creatures, but none more common than the mouse.\" Pet Battle Kun-Lau Summit --" },
        { speciesID = 728, npcID = 63585, name = "Szechuan Chicken", petType = 3, source = "drop", sourceInfo = "Szechuan Chicken \"Will only lay eggs in bright light.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 729, npcID = 63557, name = "Tolai Hare", petType = 5, source = "drop", sourceInfo = "Tolai Hare \"In the ancient fables, the first Tolai hare strode across the gulf between the stars before it upset them and they tumbled from the heavens to the world below.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 730, npcID = 63558, name = "Tolai Hare Pup", petType = 5, source = "drop", sourceInfo = "Tolai Hare Pup \"Tolai hare pups are sent from their dens at a young age to find their own way.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 731, npcID = 63555, name = "Zooey Snake", petType = 8, source = "drop", sourceInfo = "Zooey Snake \"These reptiles possess hooked scales, allowing them to slither up Kun-Lai Summit's rocky slopes and steep cliffs.\" Pet Battle Kun-Lai Summit --" },
        { speciesID = 732, npcID = 65187, name = "Amber Moth", petType = 3, source = "drop", sourceInfo = "Amber Moth \"Known to flourish in the rainy season, this insect is drawn to lightning storms.\" Pet Battle Dread Wastes, Townlong Steppes --" },
        { speciesID = 733, npcID = 63549, name = "Grassland Hopper", petType = 5, source = "drop", sourceInfo = "Grassland Hopper \"At night, the grassland hoppers fill the night with their maddening song. Those unaccustomed to it have spent many a sleepless night serenaded by their mating calls.\" Pet Battle Townlong Steppes --" },
        { speciesID = 737, npcID = 65190, name = "Mongoose", petType = 9, source = "drop", sourceInfo = "Mongoose \"Contrary to its benign appearance, mongoose are dangerous carnivores, well known for their ability to hunt venomous snakes that could kill much larger creatures.\" Pet Battle Townlong Steppes --" },
        { speciesID = 739, npcID = 63954, name = "Mongoose Pup", petType = 9, source = "drop", sourceInfo = "Mongoose Pup \"Mongoose pups prefer long grass where only their mothers can find them.\" Pet Battle Townlong Steppes --" },
        { speciesID = 740, npcID = 63957, name = "Yakrat", petType = 5, source = "drop", sourceInfo = "Yakrat \"The bond between yak and rat is a strange one, and what the rat gains out of the symbiotic relationship is a mystery.\" Pet Battle Townlong Steppes, Dread Wastes --" },
        { speciesID = 741, npcID = 64804, name = "Silent Hedgehog", petType = 8, source = "drop", sourceInfo = "Silent Hedgehog \"These hedgehogs may be silent, but often are heard the cries of those that foolishly step upon their quills.\" Pet Battle Dread Wastes --" },
        { speciesID = 742, npcID = 64242, name = "Clouded Hedgehog", petType = 8, source = "drop", sourceInfo = "Clouded Hedgehog \"Hedgehogs are not all fond of croquet nor flamingos.\" Pet Battles Dread Wastes --" },
        { speciesID = 743, npcID = 64352, name = "Rapana Whelk", petType = 5, source = "drop", sourceInfo = "Rapana Whelk \"Has been spotted fighting other whelks for prime food sources.\" Pet Battle Dread Wastes --" },
        { speciesID = 744, npcID = 64238, name = "Resilient Roach", petType = 5, source = "drop", sourceInfo = "Resilient Roach \"The roaches of the Dread Wastes dwell in the shadows. Some people swear the shadows travel with them.\" Pet Battle Dread Wastes --" },
        { speciesID = 745, npcID = 63548, name = "Crunchy Scorpion", petType = 8, source = "drop", sourceInfo = "Crunchy Scorpion \"Unique carapace is prized by trinket makers for its texture and strength.\" Pet Battle Dread Wastes --" },
        { speciesID = 746, npcID = 65203, name = "Emperor Crab", petType = 9, source = "drop", sourceInfo = "Emperor Crab \"The emperor crab was named for its regal appearance: the ridges of its shell and its raised claws eerily resembling the crown. One that would pinch your eyes out if you tried to wear it.\" Pet Battle Dread Wastes --" },
        { speciesID = 747, npcID = 63850, name = "Effervescent Glowfly", petType = 3, source = "drop", sourceInfo = "Effervescent Glowfly \"Luminescent body used to attract mates.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 748, npcID = 63838, name = "Gilded Moth", petType = 3, source = "drop", sourceInfo = "Gilded Moth \"This delicate insect's wings are often sewn into clothing and armor.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 749, npcID = 63841, name = "Golden Civet", petType = 9, source = "drop", sourceInfo = "Golden Civet \"Civets are landbound cousins of the otter and are prized for their heady musks.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 750, npcID = 63842, name = "Golden Civet Kitten", petType = 9, source = "drop", sourceInfo = "Golden Civet Kitten \"The civets are known to guard their young ferociously.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 751, npcID = 63847, name = "Dancing Water Skimmer", petType = 9, source = "drop", sourceInfo = "Dancing Water Skimmer \"Named for their apparent dancelike behavior when skimming aquatic surfaces, the species uses erratic movements to avoid being devoured by fish and other underwater predators.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 752, npcID = 63849, name = "Yellow-Bellied Bullfrog", petType = 9, source = "drop", sourceInfo = "Yellow-Bellied Bullfrog \"Despite its menacing appearance, the yellow-bellied bullfrog was aptly named.\" Pet Battle Vale of Eternal Blossoms --" },
        { speciesID = 753, npcID = 65215, name = "Garden Moth", petType = 3, source = "drop", sourceInfo = "Garden Moth \"Known to flourish in the rainy season, this insect is drawn to lightning storms.\" Pet Battle Jade Forest --" },
        { speciesID = 754, npcID = 65216, name = "Shrine Fly", petType = 3, source = "drop", sourceInfo = "Shrine Fly \"This species of insect is drawn to the latent energy in shrines, their luminescent appearance adding to the mystique of the places of power.\" Pet Battle Jade Forest --" },
        { speciesID = 834, npcID = 64634, name = "Grinder", petType = 7, source = "drop", sourceInfo = "Grinder \"Mogu sorcerers, keepers of the secret to bringing stone to life, prefer these stolid companions over more beastly familiars.\" Drop: Karr the Darkener Dread Wastes --" },
        { speciesID = 836, npcID = 64633, name = "Aqua Strider", petType = 9, source = "drop", sourceInfo = "Aqua Strider \"Water striders serve an important role in jinyu culture, acting as a mount, means of sending communications, and even a family pet.\" Drop: Nalash Verdantis Dread Wastes --" },
        { speciesID = 1128, npcID = 68506, name = "Sumprush Rodent", petType = 8, source = "drop", sourceInfo = "Sumprush Rodent \"A rodent of usual size.\" Pet Battle Krasarang Wilds --" },
        { speciesID = 1166, npcID = 68846, name = "Kun-Lai Runt", petType = 1, source = "drop", sourceInfo = "Kun-Lai Runt \"Indigenous to the peaks of Kun-Lai Summit, this rare yeti is much more dangerous than it looks.\" Pet Battle Kun-Lai Summit" },
        { speciesID = 1175, npcID = 69648, name = "Thundertail Flapper", petType = 7, source = "drop", sourceInfo = "Thundertail Flapper \"Touched by lightning, these dangerous rodents should be kept at a safe distance.\" Pet Battle Isle of Thunder --" },
        { speciesID = 1177, npcID = 69748, name = "Living Sandling", petType = 7, source = "drop", sourceInfo = "Living Sandling \"Born of sand, these dangerous creatures can form and disperse in the blink of an eye.\" Drop: Throne of Thunder Throne of Thunder --" },
        { speciesID = 1178, npcID = 69778, name = "Sunreaver Micro-Sentry", petType = 10, source = "drop", sourceInfo = "Sunreaver Micro-Sentry \"Loyal to the Sunreavers from creation, these pint-sized constructs can still pack a punch.\" Drop: Haywire Sunreaver Construct Isle of Thunder --" },
        { speciesID = 1179, npcID = 69794, name = "Electrified Razortooth", petType = 7, source = "drop", sourceInfo = "Electrified Razortooth \"Lightning can be seen flowing across its body, teeth to tail.\" Pet Battle Isle of Thunder --" },
        { speciesID = 1180, npcID = 69796, name = "Zandalari Kneebiter", petType = 8, source = "drop", sourceInfo = "Zandalari Kneebiter \"This unique raptor was born on the island of Zandalar and transported here along with the rest of the Zandalari army.\" Drop: Zandalari Dinomancer Isle of Giants --" },
        { speciesID = 1181, npcID = 69818, name = "Elder Python", petType = 8, source = "drop", sourceInfo = "Elder Python \"These snakes have been known to swallow gnomes in one gulp.\" Pet Battle Isle of Thunder --" },
        { speciesID = 1182, npcID = 69819, name = "Swamp Croaker", petType = 9, source = "drop", sourceInfo = "Swamp Croaker \"Probably best not to touch it.\" Pet Battle Isle of Thunder --" },
        { speciesID = 1183, npcID = 69820, name = "Son of Animus", petType = 10, source = "drop", sourceInfo = "Son of Animus \"Forged in the Throne of Thunder, these tiny creations are servants of the great Dark Animus.\" Drop: Animus Throne of Thunder --" },
        { speciesID = 1200, npcID = 70083, name = "Pygmy Direhorn", petType = 8, source = "drop", sourceInfo = "Pygmy Direhorn \"Don't pet the pointy end. Note: all of the ends are pointy.\" Drop: Horridon Throne of Thunder --" },
        { speciesID = 1201, npcID = 70098, name = "Spawn of G'nathus", petType = 9, source = "drop", sourceInfo = "Spawn of G'nathus \"Some Pandaren believe G'nathus to be an ancient Zandalari Loa left behind to guard the waters south of Lei Shen's Island citadel.\" Drop: G'nathus Townlong Steppes --" },
        { speciesID = 1202, npcID = 70144, name = "Ji-Kun Hatchling", petType = 3, source = "drop", sourceInfo = "Ji-Kun Hatchling \"Deadly offspring of the Ancient Mother, Ji-Kun hatchlings are considered sacred treasures in many cultures.\" Drop: Ji-Kun Throne of Thunder --" },
        { speciesID = 1205, npcID = 70154, name = "Direhorn Runt", petType = 8, source = "drop", sourceInfo = "Direhorn Runt \"The Zandalari breed specific Direhorn species for their small size for use as mounts.\" Drop: Direhorns Isle of Giants --" },
        { speciesID = 1211, npcID = 70451, name = "Zandalari Anklerender", petType = 8, source = "drop", sourceInfo = "Zandalari Anklerender \"These tiny minions of Zandalar are adept at stowing away within the cargo holds of the enormous Zandalari warships.\" Drop: Zandalari Dinomancer Isle of Giants --" },
        { speciesID = 1212, npcID = 70452, name = "Zandalari Footslasher", petType = 8, source = "drop", sourceInfo = "Zandalari Footslasher \"Even at this size, these raptors can eviscerate an entire cow in less than 10 seconds.\" Drop: Zandalari Dinomancer Isle of Giants --" },
        { speciesID = 1213, npcID = 70453, name = "Zandalari Toenibbler", petType = 8, source = "drop", sourceInfo = "Zandalari Toenibbler \"These adorable beasts are both cuddly and huggable, providing you do not enjoy having a face.\" Drop: Zandalari Dinomancer Isle of Giants --" },
        { speciesID = 1243, npcID = 71199, name = "Living Fluid", petType = 6, source = "drop", sourceInfo = "Living Fluid \"The dark pools in Primordius chamber laid stagnant after the fall of the mogu, and murky thoughts began to coalesce.\" Drop: Primordius Throne of Thunder --" },
        { speciesID = 1244, npcID = 71200, name = "Viscous Horror", petType = 6, source = "drop", sourceInfo = "Viscous Horror \"These malicious oozes are highly sensitive to Primordious' pheromone signature.\" Drop: Primordious Throne of Thunder Normal or Heroic Difficulty" },
        { speciesID = 1245, npcID = 71201, name = "Filthling", petType = 6, source = "drop", sourceInfo = "Filthling \"Battle pet trainers are strongly encouraged to wash their hands for at least 30 minutes after playing with the filthling.\" Drop: Quivering Filth Isle of Thunder --" },
        { speciesID = 1321, npcID = 73534, name = "Azure Crane Chick", petType = 3, source = "drop", sourceInfo = "Azure Crane Chick \"Crane chicks of the Timeless Isle sometimes sing a curious song that calms the nerves and soothes the soul.\" Drop: Crane Nest Timeless Isle --" },
        { speciesID = 1323, npcID = 73533, name = "Ashleaf Spriteling", petType = 1, source = "drop", sourceInfo = "Ashleaf Spriteling \"The Ashleaf Sprites of the Timeless Isle tirelessly protect the vegetation of the island from the burning fury of Ordos and his minions.\" Drop: Leafmender Timeless Isle --" },
        { speciesID = 1324, npcID = 73542, name = "Ashwing Moth", petType = 3, source = "drop", sourceInfo = "Ashwing Moth \"Jinyu assassins employ this moth as both a portable decoy and a light source to reveal weak spots in their enemy's armor.\" Pet Battle Timeless Isle --" },
        { speciesID = 1325, npcID = 73543, name = "Flamering Moth", petType = 3, source = "drop", sourceInfo = "Flamering Moth \"Cats and other curious critters often have short-lived play sessions with this moth that end with a face full of singed hair.\" Pet Battle Timeless Isle --" },
        { speciesID = 1326, npcID = 73368, name = "Skywisp Moth", petType = 3, source = "drop", sourceInfo = "Skywisp Moth \"This curious moth is sometimes found interrupting the spells of a wandering mage or warlock.\" Pet Battle Timeless Isle --" },
        { speciesID = 1328, npcID = 73356, name = "Ruby Droplet", petType = 7, source = "drop", sourceInfo = "Ruby Droplet \"The waters of Ruby Lake are colored a strange reddish hue, possibly due to the ruby crystals found deep within the mountains of the Timeless Isle.\" Drop: Garnia Timeless Isle --" },
        { speciesID = 1329, npcID = 73532, name = "Dandelion Frolicker", petType = 1, source = "drop", sourceInfo = "Dandelion Frolicker \"While fascinated by flowers, the frolicker has also been known to dance with blades of grass and the occasional weed.\" Drop: Scary Sprite Timeless Isle --" },
        { speciesID = 1330, npcID = 73364, name = "Death Adder Hatchling", petType = 8, source = "drop", sourceInfo = "Death Adder Hatchling \"Late in life, if the environmental conditions are correct, a Death Adder may shed its skin and undergo a transformation into an Imperial Python.\" Drop: Imperial Python Timeless Isle --" },
        { speciesID = 1332, npcID = 73351, name = "Gooey Sha-ling", petType = 7, source = "drop", sourceInfo = "Gooey Sha-ling \"Sha-lings reflect the emotional state of their handler, becoming agitated, depressed, fearful, or doubtful depending on the magnitude of negative thoughts around them.\" Drop: Sha of Pride Siege of Orgrimmar --" },
        { speciesID = 1333, npcID = 73355, name = "Jademist Dancer", petType = 7, source = "drop", sourceInfo = "Jademist Dancer \"The Jademist Dancers of the Timeless Isle have a curious attraction to the steam vents of the northwestern shore.\" Drop: Jademist Dancer Timeless Isle --" },
        { speciesID = 1334, npcID = 73354, name = "Kovok", petType = 8, source = "drop", sourceInfo = "Kovok \"The tiny terror of the Dread Wastes, Kovok prefers a steady diet of \"brain food:\" mushan brains, human brains, any brains really.\" This strange nutritional requirement may be tangentially related to his enormous head.\" Drop: Paragons of the Klaxxi Siege of Orgrimmar --" },
        { speciesID = 1335, npcID = 73357, name = "Ominous Flame", petType = 7, source = "drop", sourceInfo = "Ominous Flame \"The odd blue flames found within the Cavern of Lost Spirits have led many unwary adventurers to their doom.\" Drop: Foreboding Flame Timeless Isle --" },
        { speciesID = 1336, npcID = 73367, name = "Skunky Alemental", petType = 7, source = "drop", sourceInfo = "Skunky Alemental \"When the village of Pi'jiu was attacked by the Ordon Yaungol generations ago, the villagers bravely erected a keg in the center of the village. The following morning, after the celebration had died down, the still-drunken Yaungol blearily agreed to a peace treaty.\" Drop: Zhu-Ghon the Sour Timeless Isle --" },
        { speciesID = 1337, npcID = 73366, name = "Spineclaw Crab", petType = 9, source = "drop", sourceInfo = "Spineclaw Crab \"Spineclaw crabs of Pandaria have existed for thousands of years and remain one of the continent's oldest creatures.\" Drop: Monstrous Spineclaw Timeless Isle --" },
        { speciesID = 1338, npcID = 73359, name = "Gulp Froglet", petType = 9, source = "drop", sourceInfo = "Gulp Froglet \"Gulp frogs of the Timeless Isle can feast upon prey several times larger than themselves by slowly digesting the victim externally with a toxic slime.\" Drop: Bufo Timeless Isle --" },
        { speciesID = 1343, npcID = 73668, name = "Bonkers", petType = 1, source = "drop", sourceInfo = "Bonkers \"Some young and rambunctious hozen are trained from an early age to use boxing gloves so they don't accidentally kill their tribe members, and more importantly, to keep them from picking their noses.\" Drop: Kukuru Chest Timeless Isle --" },
        { speciesID = 1345, npcID = 73730, name = "Gu'chi Swarmling", petType = 5, source = "drop", sourceInfo = "Gu'chi Swarmling \"Swarmlings of Gu'chi spin an ancient, and very powerful, form of silk that has not been seen in Pandaria in ages.\" Drop: Gu'chi the Swarmbringer Timeless Isle --" },
        { speciesID = 1348, npcID = 73738, name = "Jadefire Spirit", petType = 7, source = "drop", sourceInfo = "Jadefire Spirit \"The Jadefire Spirit is thought to be a living embodiment of Yu'lon's own jade breath.\" Drop: Spirit of Jadefire Timeless Isle --" },
        { speciesID = 2579, npcID = 150354, name = "Stoneclaw", petType = 8, source = "drop", sourceInfo = "Stoneclaw \"Quilen were the favored companions of the ancient Mogu race due to their loyal nature.\" Drop: The Stone Guard Mogu' shan Vaults --" },
        { speciesID = 2580, npcID = 150356, name = "Wayward Spirit", petType = 4, source = "drop", sourceInfo = "Wayward Spirit \"Crossing into the spirit world too often can be dangerous for your health.\" Drop: Gara'jal the Spiritbinder Mogu' shan Vaults --" },
        { speciesID = 2581, npcID = 150357, name = "Comet", petType = 6, source = "drop", sourceInfo = "Comet \"The Engine of Nalak' sha is defended by many mighty beings, and many tiny beings.\" Drop: Elegon Mogu' shan Vaults --" },
        { speciesID = 2582, npcID = 150360, name = "Baoh-Xi", petType = 6, source = "drop", sourceInfo = "Baoh-Xi \"For being an inanimate object for many centuries, this statue sure moves around really well.\" Drop: Qin-xi Mogu-shan Vaults --" },
        { speciesID = 2583, npcID = 150365, name = "Azure Windseeker", petType = 2, source = "drop", sourceInfo = "Azure Windseeker \"This little cloud serpent's favorite activity is chasing its own tail.\" Drop: Tsulong Terrace of Endless Spring --" },
        { speciesID = 2584, npcID = 150372, name = "Spirit of the Spring", petType = 7, source = "drop", sourceInfo = "Spirit of the Spring \"The elemental spirits of Pandaria have been known to plan tricks to play on unsuspecting visitors years in advance.\" Drop: Lei Shi Terrace of Endless Spring --" },
        { speciesID = 2585, npcID = 150374, name = "Kor'thik Swarmling", petType = 3, source = "drop", sourceInfo = "Kor'thik Swarmling \"Don't let these eat after midnight, legend has it that it's very dangerous.\" Drop: Imperial Vizier Zor' lok Heart of Fear --" },
        { speciesID = 2586, npcID = 150375, name = "Amberglow Stinger", petType = 3, source = "drop", sourceInfo = "Amberglow Stinger \"The glow emanating from these is both calming and eerie at the same time when in total darkness.\" Drop: Blade Lord Ta'yak Heart of Fear --" },
        { speciesID = 2587, npcID = 150377, name = "Spawn of Garalon", petType = 8, source = "drop", sourceInfo = "Spawn of Garalon \"The kunchong are extremely aggressive and will eat just about anything they can as soon as they care able to walk. If they can't eat it, they will smash it instead.\" Drop: Garalon Heart of Fear --" },
        { speciesID = 2589, npcID = 150380, name = "Living Amber", petType = 6, source = "drop", sourceInfo = "Living Amber \"The mantid are extremely reliant upon amber for many things, and even use it in some of their magic.\" Drop: Amber-Shaper Un-sok Heart of Fear --" },
        { speciesID = 2590, npcID = 150381, name = "Ravenous Prideling", petType = 7, source = "drop", sourceInfo = "Ravenous Prideling \"As a spawn of the most dangerous sha, this little monster has some big plans, but needs to wait a few thousand years first.\" Drop: Grand Empress Shek'zeer Heart of Fear --" },
    } },
    { source = "achievement", pets = {
        { speciesID = 835, npcID = 64632, name = "Hopling", petType = 1, source = "achievement", sourceInfo = "Hopling \"The great big world can be a dangerous place for such a tiny, adorable creature.\" Achievement: Ling-Ting's Herbal Journey Stormstout Brewery --" },
    } },
    { source = "quest", pets = {
        { speciesID = 847, npcID = 62829, name = "Fishy", petType = 9, source = "quest", sourceInfo = "Fishy \"Many believe (incorrectly) that goldfish have no memories. Trainers who have worked with them know this is clearly not the case and have the bruises to prove it.\" Quest: Let Them Burn The Jade Forest --" },
        { speciesID = 868, npcID = 66950, name = "Pandaren Water Spirit", petType = 7, source = "quest", sourceInfo = "Pandaren Water Spirit \"Water spirits are especially mischievous and are known to frequent the canals of the Stormstout Brewery.\" Quest: Pandaren Spirit Tamer Vale of Eternal Blossoms --" },
        { speciesID = 1042, npcID = 63370, name = "Red Cricket", petType = 5, source = "quest", sourceInfo = "Red Cricket \"Be careful, he might eat all your crops!\" Quest: Sho, Requires Exalted Friendship Faction Valley of the Four Winds --" },
        { speciesID = 1124, npcID = 68466, name = "Pandaren Fire Spirit", petType = 7, source = "quest", sourceInfo = "Pandaren Fire Spirit \"Though it appears to be a vaguely-related cousin to the Cinder Kitten, the two creatures actually share no ancestry.\" Quest: Pandaren Spirit Tamer Vale of Eternal Blossoms --" },
        { speciesID = 1125, npcID = 68467, name = "Pandaren Air Spirit", petType = 7, source = "quest", sourceInfo = "Pandaren Air Spirit \"These spirits represent the heart of Pandaria's elemental powers.\" Quest: Pandaren Spirit Tamer Vale of Eternal Blossoms --" },
        { speciesID = 1126, npcID = 68468, name = "Pandaren Earth Spirit", petType = 7, source = "quest", sourceInfo = "Pandaren Earth Spirit \"The elements of Pandaria can be cute and playful, until their homeland is threatened.\" Quest: Pandaren Spirit Tamer Vale of Eternal Blossoms --" },
        { speciesID = 1176, npcID = 69649, name = "Red Panda", petType = 8, source = "quest", sourceInfo = "Red Panda \"Can you believe how cute I am? Me neither.\" Quest: Beasts of Fable -- --" },
        { speciesID = 1185, npcID = 69848, name = "Spectral Porcupette", petType = 6, source = "quest", sourceInfo = "Spectral Porcupette \"Something about this creature looks familiar…\" Quest: A Large Pile of Giant Dinosaur Bones Isle of Giants --" },
        { speciesID = 1196, npcID = 69891, name = "Sunfur Panda", petType = 8, source = "quest", sourceInfo = "Sunfur Panda \"These cuddly rascals enjoy basking in the sun, sleeping in the sun, and napping in the sun.\" Quest: Beasts of Fable -- --" },
        { speciesID = 1197, npcID = 69893, name = "Snowy Panda", petType = 8, source = "quest", sourceInfo = "Snowy Panda \"The white fur of the Snowy Panda allows it to hide in the snowbanks of Kun-Lai Summit Quest: Beasts of Fable -- --" },
        { speciesID = 1198, npcID = 69892, name = "Mountain Panda", petType = 8, source = "quest", sourceInfo = "Mountain Panda \"Cousin to Snowy Panda, Mountain Panda reside in the lower regions of Kun-Lai Summit.\" Quest: Beasts of Fable -- --" },
    } },
    { source = "profession", pets = {
        { speciesID = 844, npcID = 64899, name = "Mechanical Pandaren Dragonling", petType = 10, source = "profession", sourceInfo = "Mechanical Pandaren Dragonling \"Constructed from a seemingly impossible mass of gears, springs, wires, and a little something special, this dragonling embodies the spirit of Pandaria as seen through an engineer's goggles.\" Profession: Mists of Pandaria Engineering -- --" },
        { speciesID = 845, npcID = 61877, name = "Jade Owl", petType = 6, source = "profession", sourceInfo = "Jade Owl \"Jade is naturally rich with life and color, making it the perfect raw material for this gentle companion. It is said the wind created by their wings can soothe the troubled mind.\" Profession: Mists of Pandaria Jewelcrafting -- --" },
        { speciesID = 846, npcID = 61883, name = "Sapphire Cub", petType = 6, source = "profession", sourceInfo = "Sapphire Cub \"While each cub is crafted in the same fashion, tiny imperfections in the gemstones create a unique personality when imbued with life. They are, however, always playful and friendly.\" Profession: Mists of Pandaria Jewelcrafting -- --" },
        { speciesID = 849, npcID = 66104, name = "Chi-Ji Kite", petType = 3, source = "profession", sourceInfo = "Chi-Ji Kite \"A beautiful kite brought to life by the scribes of Pandaria.\" Profession: Mists of Pandaria Inscription -- --" },
        { speciesID = 850, npcID = 66105, name = "Yu'lon Kite", petType = 3, source = "profession", sourceInfo = "Yu'lon Kite \"Who knew scribes could make kites?\" Profession: Mists of Pandaria Inscription -- --" },
        { speciesID = 1039, npcID = 67230, name = "Imperial Moth", petType = 3, source = "profession", sourceInfo = "Imperial Moth \"The larval form of this moth is world-renowned for creating the finest silk in Azeroth.\" Profession: Mists of Pandaria Tailoring (Imperial Silk) -- --" },
        { speciesID = 1204, npcID = 70082, name = "Pierre", petType = 10, source = "profession", sourceInfo = "Pierre \"Every cook's dream wrapped up in a perfect bundle of metal and bolts. Too bad what he cooks up isn't suitable for humanoid consumption. According to Jard's notes, he intends to make this little guy for his friend, Emily Cole.\" Profession: Mists of Pandaria Engineering -- --" },
        { speciesID = 1206, npcID = 70257, name = "Tiny Red Carp", petType = 9, source = "profession", sourceInfo = "Tiny Red Carp \"The red scales on these fish are believed to be a warning to predators of the Townlong Steppes and the Dread Wastes that their flesh is toxic. Dedicated fishermen can sometimes befriend one.\" Profession: Mists of Pandaria Fishing -- --" },
        { speciesID = 1207, npcID = 70258, name = "Tiny Blue Carp", petType = 9, source = "profession", sourceInfo = "Tiny Blue Carp \"These little guys can be found in the waters of the Timeless Isle, or swimming alongside Jewel Danio or Redbelly Mandarin. Dedicated fishermen can sometimes befriend one.\" Profession: Mists of Pandaria Fishing -- --" },
        { speciesID = 1208, npcID = 70259, name = "Tiny Green Carp", petType = 9, source = "profession", sourceInfo = "Tiny Green Carp \"It is believed that the green coloration and stripes on the tiny green carp serve as camouflage in the waters of the Jade Forest, Valley of the Four Winds and the Krasarang Wilds. Dedicated fishermen can sometimes befriend one.\" Profession: Mists of Pandaria Fishing -- --" },
        { speciesID = 1209, npcID = 70260, name = "Tiny White Carp", petType = 9, source = "profession", sourceInfo = "Tiny White Carp \"These hardy fish can survive in a wide range of climates, from the snow-capped mountains of Kun-Lai Summit to the temperate, salty waters of the oceans around Pandaria. Dedicated fishermen can sometimes befriend one too.\" Profession: Mists of Pandaria Fishing -- --" },
        { speciesID = 1256, npcID = 71693, name = "Rascal-Bot", petType = 10, source = "profession", sourceInfo = "Rascal-Bot \"This little guy seems to like to hang out at the fringes of cataclysmic events. There is no evidence to suggest he has anything to do with the cause of these events, though — he's probably just an observer. Or maybe he just gets lost on his trek to other places.\" Profession: Mists of Pandaria Engineering -- --" },
    } },
    { source = "vendor", pets = {
        { speciesID = 652, npcID = 63559, name = "Tiny Goldfish", petType = 9, source = "vendor", sourceInfo = "Tiny Goldfish \"This bubble is way worse than a tank.\" Vendor: Nat Pagle Krasarang Wilds Faction: The Anglers – Honored 250 Gold" },
        { speciesID = 792, npcID = 65314, name = "Jade Crane Chick", petType = 3, source = "vendor", sourceInfo = "Jade Crane Chick \"A graceful creature from the isle of Pandaria.\" Vendor: Audrey Burnhep, Varzok Stormwind, Orgrimmar 50 Silver" },
        { speciesID = 817, npcID = 65323, name = "Wild Jade Hatchling", petType = 2, source = "vendor", sourceInfo = "Wild Jade Hatchling \"So cute, yet so epic.\" Pet Battle The Jade Forest Faction: Order of the Cloud Serpent - Exalted" },
        { speciesID = 818, npcID = 65324, name = "Wild Golden Hatchling", petType = 2, source = "vendor", sourceInfo = "Wild Golden Hatchling \"The offspring of Tsulong, hidden away before the corruption of the Sha had fully taken hold of the Terrace of Endless Spring.\" Pet Battle The Jade Forest Faction: Order of the Cloud Serpent - Exalted" },
        { speciesID = 819, npcID = 65321, name = "Wild Crimson Hatchling", petType = 2, source = "vendor", sourceInfo = "Wild Crimson Hatchling \"It's red, so it must fly faster.\" Pet Battle The Jade Forest Faction: Order of the Cloud Serpent - Exalted" },
        { speciesID = 1266, npcID = 71942, name = "Xu-Fu, Cub of Xuen", petType = 8, source = "vendor", sourceInfo = "Xu-Fu, Cub of Xuen \"Fierce and loyal, Xu-Fu loves to hunt by moonlight. Once during a full moon, he killed and ate an entire Ironfur Great Bull, prompting a two-day nap.\" Vendor: Tournament of Celestials Timeless Isle --" },
        { speciesID = 1304, npcID = 72463, name = "Yu'la, Broodling of Yu'lon", petType = 2, source = "vendor", sourceInfo = "Yu'la, Broodling of Yu'lon \"A master sculptor devoted her life to creating an incomparably beautiful statue, inspired by her love and reverence for Yu'lon. When the sculptor passed away, Yu'lon breathed a fraction of her essence into the statue, bringing Yu'la into the world.\" Vendor: Master Li Timeless Isle 3 Celestial Coins" },
        { speciesID = 1305, npcID = 72464, name = "Zao, Calfling of Niuzao", petType = 8, source = "vendor", sourceInfo = "Zao, Calfling of Niuzao \"Always on the lookout for a fight or some tasty grass, Zao keeps his head down and eyes forward.\" Vendor: Tournament of Celestials Timeless Isle --" },
        { speciesID = 1311, npcID = 72285, name = "Chi-Chi, Hatchling of Chi-Ji", petType = 3, source = "vendor", sourceInfo = "Chi-Chi, Hatchling of Chi-Ji \"Chi-Chi tries to inspire hope with her loud squawk and by chasing and eventually eating, butterflies.\" Vendor: Master Li Timeless Isle 3 Celestial Coins" },
        { speciesID = 1344, npcID = 73688, name = "Vengeful Porcupette", petType = 8, source = "vendor", sourceInfo = "Vengeful Porcupette \"One of the beasts left on the Timeless Isle when it shifted through time, most likely sacrificed by the Ordon to their demigod, Ordos.\" Vendor: Speaker Gulan Timeless Isle 100 Bloody Coins" },
        { speciesID = 1346, npcID = 73732, name = "Harmonious Porcupette", petType = 6, source = "vendor", sourceInfo = "Harmonious Porcupette \"Prolonged exposure to Shaohao's tranquil mists has calmed these sprites, which act as peaceful companions to the Mistweavers.\" Vendor: Mistweaver Ku Timeless Isle Faction: Shaohao – Revered 7,500 Timeless Coins" },
        { speciesID = 1350, npcID = 73809, name = "Sky Lantern", petType = 3, source = "vendor", sourceInfo = "Sky Lantern \"A candle inside of the kite heats the air, causing it to rise into the air without the need for wind.\" Vendor: Ku-Mo Timeless Isle --" },
        { speciesID = 2017, npcID = 118060, name = "Infinite Hatchling", petType = 2, source = "vendor", sourceInfo = "Infinite Hatchling \"The infinite dragonflight is far more diverse than most denizens of Azeroth know.\" Vendor: Mistweaver Xia Timeless Isle 2,200 Timewarped Badges" },
        { speciesID = 2018, npcID = 118063, name = "Paradox Spirit", petType = 7, source = "vendor", sourceInfo = "Paradox Spirit \"It is a riddle wrapped in a mystery inside an enigma.\" Vendor: Mistweaver Xia Timeless Isle 2,200 Timewarped Badges" },
    } },
})
